#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int cmp(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int R, N;
    if (scanf("%d %d", &R, &N) != 2) return 0;

    int minprice[101];
    int present[101];
    memset(present, 0, sizeof(present));
    for (int i = 1; i <= 100; i++) minprice[i] = 101; /* preco maximo = 100 */

