        if (scanf("%d %d", &T, &P) != 2) return 0;
        if (!present[T] || P < minprice[T]) {
            present[T] = 1;
            minprice[T] = P;
        }
    }

    int prices[100], cnt = 0;
    for (int i = 1; i <= 100; i++) {
        if (present[i]) prices[cnt++] = minprice[i];
    }

    /* Para maximizar a QUANTIDADE de tipos distintos, basta comprar
       cada tipo pelo menor preco e escolher gulosamente os mais baratos. */
    qsort(prices, cnt, sizeof(int), cmp);

    int sum = 0, ans = 0;
    for (int i = 0; i < cnt; i++) {
        if (sum + prices[i] <= R) {
            sum += prices[i];
            ans++;
        } else {
            break;
        }
    }

    printf("%d\n", ans);
    return 0;
}
